"use server";

import { serverAction } from "rwsdk/worker";

export interface Todo {
  id: string;
  title: string;
  done: boolean;
  createdAt: number;
}

const KV_PREFIX = "todo:";

async function getKV() {
  const { env } = await import("cloudflare:workers");
  return env.TODOS;
}

export async function getAllTodos(): Promise<Todo[]> {
  const kv = await getKV();
  const list = await kv.list({ prefix: KV_PREFIX });
  const todos: Todo[] = [];
  for (const key of list.keys) {
    const value = await kv.get(key.name);
    if (value) {
      todos.push(JSON.parse(value));
    }
  }
  todos.sort((a, b) => a.createdAt - b.createdAt);
  return todos;
}

export const addTodo = serverAction(async (formData: FormData) => {
  const title = String(formData.get("title") || "").trim();
  if (!title) return;
  const kv = await getKV();
  const todo: Todo = {
    id: crypto.randomUUID(),
    title,
    done: false,
    createdAt: Date.now(),
  };
  await kv.put(`${KV_PREFIX}${todo.id}`, JSON.stringify(todo));
  return todo;
});

export const toggleTodo = serverAction(async (formData: FormData) => {
  const id = String(formData.get("id") || "");
  const done = formData.get("done") === "on" || formData.get("done") === "true";
  if (!id) return;
  const kv = await getKV();
  const value = await kv.get(`${KV_PREFIX}${id}`);
  if (!value) return;
  const todo: Todo = JSON.parse(value);
  todo.done = done;
  await kv.put(`${KV_PREFIX}${id}`, JSON.stringify(todo));
  return todo;
});

export const deleteTodo = serverAction(async (formData: FormData) => {
  const id = String(formData.get("id") || "");
  if (!id) return;
  const kv = await getKV();
  await kv.delete(`${KV_PREFIX}${id}`);
  return { id };
});
EOF

