"use client";

import React from "react";
import { addTodo, toggleTodo, deleteTodo, getAllTodos, Todo } from "../actions";

export async function Home() {
  const todos = await getAllTodos();
  const remaining = todos.filter((t) => !t.done).length;

  return (
    <div style={{ maxWidth: 600, margin: "2rem REDACTED", fontFamily: "sans-serif" }}>
      <h1>Todos</h1>

      <form action={addTodo}>
        <input
          name="title"
          aria-label="New todo title"
          placeholder="What needs to be done?"
          style={{ padding: "0.5rem", width: "70%" }}
        />
        <button type="submit" style={{ padding: "0.5rem 1rem" }}>
          Add
        </button>
      </form>

      <p>
        <span data-testid="remaining-count">{remaining}</span> remaining
      </p>

      <ul style={{ listStyle: "none", padding: 0 }}>
        {todos.map((todo: Todo) => (
          <li
            key={todo.id}
            data-done={todo.done ? "true" : "false"}
            style={{
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
              padding: "0.5rem 0",
              borderBottom: "1px solid #eee",
